const mutants = {
  scopeIgnored: [S, ()=>{P.settleOpenCallsOnStreamFailure=function(r){return orig.settleOpenCallsOnStreamFailure.call(this,r);};}],
  rejectScopeIgnored: [S, ()=>{P.recordAbortedApproval=function(o,r){return orig.recordAbortedApproval.call(this,o,r);};}],
  dispatchLost: [S, ()=>{P.markDispatched=function(){};}],
  importCountsEntries: [S, ()=>{P.import=function(e){orig.import.call(this,e);for(let i=0;i<0;i++);/* rewind to entry count */ const n=e.length; const self=this; let t; while(true){t=orig.beginTurn.call(self); if(t===`turn-${n}`) break; if(+t.slice(5)>n){break;}} };}],
  importNoRewind: [S, ()=>{P.import=function(e){orig.import.call(this,[]); /* drops entries */};}],
  exportDropsCompletedOutput: [S, ()=>{P.export=function(){return orig.export.call(this).map(e=>e.status==="completed"?{...e,output:""}:e);};}],
  anchorStampIgnored: [R, ()=>{P.setUserTurnCountSource=function(){};}],
  exportDropsSyntheticResult: [R, ()=>{P.export=function(){return orig.export.call(this).map(e=>e.status==="unknown"?{...e,historyItems:e.historyItems?.slice(0,1)}:e);};}],
  exportDuplicatesPairItems: [R, ()=>{P.export=function(){return orig.export.call(this).map(e=>e.status==="completed"&&e.historyItems?.length>=2?{...e,historyItems:[...e.historyItems,...e.historyItems]}:e);};}],
  exportReordersPair: [R, ()=>{P.export=function(){return orig.export.call(this).map(e=>e.historyItems?.length>=2?{...e,historyItems:[...e.historyItems].reverse()}:e);};}],
  exportAltersArgs: [R, ()=>{P.export=function(){return orig.export.call(this).map(e=>e.historyItems?.length>=2?{...e,historyItems:e.historyItems.map(i=>i.type==="function_call"?{...i,arguments:"{}"}:i)}:e);};}],
};
for (const [name,[prop,apply]] of Object.entries(mutants)) {
  for (const k in orig) P[k]=orig[k]; apply();
  const r = fc.check(prop,{numRuns:1000,seed:4242});
  console.log(name, r.failed?"RED":"green", r.numRuns, r.failed?String(r.errorInstance?.message).split("\n")[0].slice(0,90):"");
}
for (const k in orig) P[k]=orig[k];
console.log("restored", fc.check(S,{numRuns:300,seed:1}).failed, fc.check(R,{numRuns:300,seed:1}).failed);
'; echo exit=$?

