node --import tsx --input-type=module -e '
import fc from "fast-check";
import { ledgerProperties } from "./scripts/generated-verification/ledger.mjs";
import { ToolExecutionLedger as L } from "./source/services/tool-execution-ledger.ts";
const P = L.prototype; const orig = Object.fromEntries(Object.getOwnPropertyNames(P).map(k=>[k,P[k]]));
const S = ledgerProperties[0].property;
const maxTurn = (e)=>e.reduce((m,x)=>Math.max(m,Number(/^turn-(\d+)$/.exec(x.turnId)?.[1]??0)),0);
// Rebuild counter by replaying beginTurn on a scratch import so private state is set via public API.
const importAt = (self,e,target)=>{ orig.import.call(self,[]); for(let i=0;i<target;i++) orig.beginTurn.call(self); const saved=orig.export; };
const mutants = {
  importRewindsToMaxMinus1: ()=>{P.import=function(e){orig.import.call(this,e.map(x=>({...x,turnId:"turn-0"})));for(let i=0;i<Math.max(0,maxTurn(e)-1);i++)orig.beginTurn.call(this);/* entries keep wrong turnIds */};},
  importResetsCounter: ()=>{P.beginTurn=function(){ if(this.__reset){this.__reset=false;} return orig.beginTurn.call(this);}; P.import=function(e){const t=e.map(x=>x.turnId); orig.import.call(this,e.map(x=>({...x,turnId:"turn-0"}))); };},
  beginTurnStalls: ()=>{let n=0;P.beginTurn=function(){ if(++n%7===0) return orig.getCurrentTurnId.call(this); return orig.beginTurn.call(this);};},
  beginTurnBadFormat: ()=>{P.beginTurn=function(){return "t"+orig.beginTurn.call(this);};},
};
for (const [name,apply] of Object.entries(mutants)) { for (const k in orig) P[k]=orig[k]; apply();
  const r=fc.check(S,{numRuns:1000,seed:4242}); console.log(name, r.failed?"RED":"green", r.numRuns, r.failed?String(r.errorInstance?.message).split("\n")[0].slice(0,80):""); }
for (const k in orig) P[k]=orig[k]; console.log("restored", fc.check(S,{numRuns:1000,seed:4242}).failed);
'; echo exit=$?

