// Collision after import: first beginTurn after import returns the imported max (reuse), entries untouched.
P.import=function(e){orig.import.call(this,e); this.__collide=maxTurn(e)>0?maxTurn(e):null;};
P.beginTurn=function(){ if(this.__collide!=null){const id=`turn-${this.__collide}`;this.__collide=null;return id;} return orig.beginTurn.call(this);};
run("importCollidesWithMax");
for (const k in orig) P[k]=orig[k];
// Valid gap: import skips ahead 3 turns; must remain green under narrowed oracle.
P.import=function(e){orig.import.call(this,e); for(let i=0;i<3;i++) orig.beginTurn.call(this);};
run("importGapAllowed");
for (const k in orig) P[k]=orig[k];
// Valid gap on ordinary turns: every beginTurn skips one number.
P.beginTurn=function(){orig.beginTurn.call(this);return orig.beginTurn.call(this);};
run("turnGapAllowed");
for (const k in orig) P[k]=orig[k]; run("restored");
'; echo exit=$?

